css:
#tongsci1-3-2-1-1-freefall .head.split .sf-ask { font-size: 40px; white-space: normal; max-width: 640px; text-align: right; line-height: 1.15; margin: 0; }
#tongsci1-3-2-1-1-freefall .sf-body { grid-template-columns: 900px minmax(0, 1fr); }
.sf-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #0b0d12; }
.sf-stage canvas { touch-action: none; cursor: grab; }
.sf-panel { gap: 12px; }
.sf-out { margin: 0; font-size: 22px; line-height: 1.55; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 3.3em; flex: none; }
.sf-out b { color: var(--accent); }
.sf-out small { font-size: 19px; color: var(--ink-2); }

.sf-tab { width: 100%; border-collapse: collapse; table-layout: fixed; font: 600 21px/1.3 var(--f-body); flex: none; background: var(--paper-2); border: 2px solid var(--ink); }
.sf-tab th { font: 700 19px/1.25 var(--f-body); background: color-mix(in srgb, var(--accent) 12%, var(--paper-2)); border: 1.5px solid var(--ink-3); padding: 5px 6px; }
.sf-tab td { border: 1.5px solid var(--rule, #c9ccd3); padding: 3px 8px; text-align: center; height: 34px; font-family: var(--f-mono); }
.sf-tab td:first-child { font-family: var(--f-body); color: var(--ink-2); }
.sf-tab td.d:empty::after, .sf-tab td.v:empty::after { content: "?"; color: var(--ink-3); opacity: .5; }
.sf-tab td em { font-style: normal; font: 700 17px var(--f-body); color: var(--good); margin-left: 4px; }
.sf-tab tr.new td { background: color-mix(in srgb, var(--hl) 55%, #fff); transition: background .4s; }

.sf-graph { flex: 1 1 auto; min-height: 150px; border: 2px solid var(--ink); border-radius: 12px; background: var(--paper-2); cursor: pointer; display: flex; outline: none; }
.sf-graph svg { width: 100%; height: 100%; display: block; }
.sf-graph.ready { border-color: var(--accent); box-shadow: 0 0 0 4px color-mix(in srgb, var(--hl) 80%, transparent); animation: sf-breath 1.6s ease-in-out infinite; }
.sf-graph.bad { animation: u-shake .45s ease; }
.sf-graph:focus-visible { outline: 4px solid var(--hl); outline-offset: 2px; }
@keyframes sf-breath { 50% { box-shadow: 0 0 0 9px color-mix(in srgb, var(--hl) 45%, transparent); } }
.sf-graph text { font: 600 19px var(--f-body); fill: var(--ink-2); }
.sf-graph text.lab { font-weight: 700; fill: var(--ink); }
.sf-graph text.hint { font-weight: 700; fill: var(--accent); }
.sf-graph text.tl { font: 700 19px var(--f-body); fill: #b8461f; }
.sf-graph text.sl { font: 800 24px var(--f-body); fill: #fff; }
.sf-graph rect.sbox { fill: var(--accent); }
.sf-graph .gl { stroke: var(--rule, #d6d9df); stroke-width: 1; }
.sf-graph .ax { stroke: var(--ink); stroke-width: 2.5; }
.sf-graph .fit { stroke: var(--accent); stroke-width: 3; stroke-dasharray: 8 7; }
.sf-graph .tri { fill: none; stroke: #b8461f; stroke-width: 3; stroke-dasharray: 6 5; }
.sf-graph .pt { fill: #f2b61c; stroke: var(--ink); stroke-width: 2.5; }
.sf-graph .pt.new { fill: #ffd84d; stroke-width: 3.5; }
#tongsci1-3-2-1-1-freefall.u-done .sf-graph { flex: 1 1 auto; }

.sf-photo { position: absolute; right: 14px; top: 14px; z-index: 4; margin: 0; width: 150px; background: #0b0d12; border: 2px solid #e9edf3; border-radius: 10px; overflow: hidden; cursor: zoom-in; display: flex; flex-direction: column; }
.sf-photo img { display: block; width: 100%; height: 330px; object-fit: contain; }
.sf-photo figcaption { font: 700 18px/1.3 var(--f-body); color: #fbfcf9; padding: 6px 8px; border-top: 2px solid #e9edf3; background: #1d2433; }
.sf-photo figcaption b { display: block; }
.sf-photo small { display: block; font: 500 18px/1.3 var(--f-body); color: #cfd6e2; }
.sf-photo .sf-ph-more { display: none; }
.sf-photo:focus-visible { outline: 4px solid var(--hl); outline-offset: 2px; }
.sf-photo.big { left: 14px; right: 14px; top: 14px; bottom: 14px; width: auto; flex-direction: row; cursor: zoom-out; box-shadow: 0 20px 50px rgba(0, 0, 0, .5); }
.sf-photo.big img { width: auto; height: 100%; object-fit: contain; flex: none; }
.sf-photo.big figcaption { flex: 1 1 auto; border-top: 0; border-left: 2px solid #e9edf3; padding: 28px 30px; font-size: 28px; display: flex; flex-direction: column; gap: 16px; justify-content: center; }
.sf-photo.big .sf-ph-more { display: block; font: 500 26px/1.6 var(--f-body); color: #e9edf3; }
.sf-photo.big small { font-size: 20px; }

